package Ascii

// N# recognizes a range-predicate count and emits masked SIMD:
// packed compares -> 0/1 lane masks -> Vector<int> accumulate.
[hot]
func CountAscii(data: ReadOnlySpan<int>): int {
    count := 0
    foreach x in data {
        // branchless: the two compares become a lane mask, not a jump
        let inRange = x >= 32 && x <= 126
        count += inRange ? 1 : 0
    }
    return count
}

