static int CountAscii(ReadOnlySpan<int> data)
{
    int count = 0;
    foreach (int x in data)
    {
        if (x >= 32 && x <= 126)
            count++;
    }
    return count;
}

rust.code:
// Branchless count over a slice; LLVM auto-vectorizes the masked add.
fn count_ascii(data: &[i32]) -> u32 {
    let mut count = 0u32;
    for &x in data {
        // (x >= 32 && x <= 126) as u32 is a 0/1 mask, no branch
        count += ((x >= 32) & (x <= 126)) as u32;
    }
    count
}

