// N# systems lane: the compiler recognizes this min/max reduction shape
// and emits System.Numerics.Vector<int> codegen (Vector.Min / Vector.Max)
// instead of a scalar loop. min & max are associative + commutative.
[hot]
func MinMaxDelta(a: int[]): int {
    if a.Length == 0 { return 0 }
    min := a[0]
    max := a[0]
    // lowered to lane-wise Vector.Min/Vector.Max over Vector<int>.Count-wide
    // chunks (4 lanes on the measured M4/NEON, 8 on AVX2), with 4 independent
    // accumulators, then a horizontal fold + scalar tail.
    for i := 1; i < a.Length; i++ {
        if a[i] < min { min = a[i] }
        if a[i] > max { max = a[i] }
    }
    return max - min
}

csharp.code:
// C# baseline: idiomatic, correct — and RyuJIT emits a SCALAR loop.
// One compare-and-update per element; no auto-vectorization.
static int MinMaxDelta(int[] a)
{
    if (a.Length == 0) return 0;
    int min = a[0];
    int max = a[0];
    for (int i = 1; i < a.Length; i++)
    {
        if (a[i] < min) min = a[i];
        if (a[i] > max) max = a[i];
    }
    return max - min;
}

