fn min_max_delta(a: &[i32]) -> i32 {
    if a.is_empty() { return 0; }
    let mut min = a[0];
    let mut max = a[0];
    for &v in &a[1..] {
        if v < min { min = v; }
        if v > max { max = v; }
    }
    max - min
}

