func CountTransitions(values: int[]): int {
    if values.Length == 0 { return 0 }

    transitions := 0
    previous := values[0]
    len := values.Length
    // carried dependency (previous) blocks SIMD — stays scalar.
    // JIT proves 1 <= i < len, so the bounds check is elided.
    for i := 1; i < len; i++ {
        current := values[i]
        if current != previous { transitions = transitions + 1 }
        previous = current
    }
    return transitions
}

