// Systems N#: concrete element type, constrained generic, zero boxing.
// [hot] makes the compiler PROVE no box / no virtual dispatch happens.
[hot]
func SumInts(values: int[]): int {
    sum := 0
    foreach v in values {
        sum = sum + v          // plain int add, stays in a register
    }
    return sum
}

