// C# scalar baseline: also allocation-free IF you stay concrete.
// The trap is how easy it is to NOT — and nothing warns you.
static int SumInts(int[] values)
{
    int sum = 0;
    foreach (int v in values)
        sum += v;              // fast path: int add, no heap
    return sum;
}

// The hidden-cost version that looks just as innocent:
static int SumBoxed(int[] values)
{
    object acc = 0;            // boxes
    foreach (int v in values)
        acc = (int)acc + v;    // unbox, add, RE-BOX every iteration
    return (int)acc;           // N allocations the compiler never mentions
}

